/* ---------- raymarched merging wax (smooth-union SDF) ---------- */
const blobPosArr=[]; const blobMetaArr=[];
for(let i=0;i<MAX_BLOBS;i++){ blobPosArr.push(new THREE.Vector4(0,-10,0,0.001)); blobMetaArr.push(new THREE.Vector3(1,0.5,i*3.7)); }
const waxUniforms = {
  uBlobs:{ value: blobPosArr },
  uMeta:{ value: blobMetaArr },
  uWaxColor:{ value: PRESETS[0].wax.clone() },
  uBulbColor:{ value: PRESETS[0].bulb.clone() },
  uTime:{ value:0 },
  uHeat:{ value:1 },
  uSteps:{ value:52 },
};
const waxVert = /* glsl */`
  varying vec3 vWorld;
  void main(){ vec4 wp = modelMatrix * vec4(position,1.0); vWorld = wp.xyz; gl_Position = projectionMatrix * viewMatrix * wp; }
`;
const waxFrag = /* glsl */`
  precision highp float;
  varying vec3 vWorld;
  uniform vec4 uBlobs[${MAX_BLOBS}];
  uniform vec3 uMeta[${MAX_BLOBS}];
  uniform vec3 uWaxColor; uniform vec3 uBulbColor; uniform float uTime; uniform float uHeat; uniform int uSteps;
  float vesselR(float y){
    float t = clamp((y-0.92)/2.10, 0.0, 1.0);
    float r = mix(0.68, 0.315, pow(t, 0.92));
    if(t>0.86){ float u=(t-0.86)/0.14; r*=sqrt(max(0.18, 1.0-u*u*0.72)); }
    if(t<0.04){ float u=t/0.04; r*=0.82+0.18*u; }
    return r;
  }
  float smin(float a, float b, float k){
    float h = clamp(0.5+0.5*(b-a)/k, 0.0, 1.0);
    return mix(b, a, h) - k*h*(1.0-h);
  }
  float sdEllipsoid(vec3 p, vec3 r){
    float k0 = length(p/r); float k1 = length(p/(r*r));
    return k0*(k0-1.0)/max(k1, 1e-4);
  }
  float mapWax(vec3 p, out float outTemp){
    float d = 1e5; float tempAcc = 0.0; float wAcc = 0.0;
    for(int i=0;i<${MAX_BLOBS};i++){
      vec4 B = uBlobs[i]; if(B.w < 0.002) continue;
      vec3 meta = uMeta[i];
      vec3 q = p - B.xyz;
      q.x += sin(q.y*6.0 + uTime*1.4 + meta.z)*0.014;
      q.z += cos(q.y*5.0 + uTime*1.1 + meta.z*1.7)*0.014;
      vec3 radii = vec3(B.w*0.94, B.w*meta.x, B.w*0.94);
      float db = sdEllipsoid(q, radii);
      float nd = smin(d, db, 0.22);
      float w = exp(-max(db,0.0)*6.0);
      tempAcc += meta.y * w; wAcc += w;
      d = nd;
    }
    outTemp = wAcc>0.001 ? tempAcc/wAcc : 0.4;
