  }
  vec2 boxHit(vec3 ro, vec3 rd, vec3 c, vec3 h){
    vec3 m=1.0/rd; vec3 n=m*(ro-c); vec3 k=abs(m)*h;
    vec3 t1=-n-k; vec3 t2=-n+k;
    return vec2(max(max(t1.x,t1.y),t1.z), min(min(t2.x,t2.y),t2.z));
  }
  void main(){
    vec3 ro = cameraPosition;
    vec3 rd = normalize(vWorld - ro);
    vec3 bc = vec3(0.0, 1.97, 0.0); vec3 bh = vec3(0.80, 1.14, 0.80);
    vec2 tt = boxHit(ro, rd, bc, bh);
    if(tt.x > tt.y || tt.y < 0.0) discard;
    float tNear = max(tt.x, 0.0); float tFar = tt.y;
    float t = tNear; float hitT = -1.0; float hitTemp = 0.5;
