    float wrapDiff = clamp((dot(N,L)+0.65)/1.65, 0.0, 1.0);
    float fres = pow(1.0 - max(dot(N,V),0.0), 3.0);
    float sss = pow(clamp(dot(V,-L)*0.5+0.5, 0.0, 1.0), 3.0) * exp(-thick*2.6);
    float bulbGlow = exp(-Ldist*1.15) * (0.55+0.75*hitTemp) * uHeat;
    vec3 deep = uWaxColor * 0.42;
    vec3 thin = mix(uWaxColor, vec3(1.0,0.92,0.78), 0.35) * 1.25;
