  const b=document.createElement('button'); b.className='preset'+(i===0?' active':''); b.title=p.name;
  b.innerHTML=`<i style="background:linear-gradient(135deg,#${p.wax.getHexString()} 0 55%,#${p.liquid.getHexString()} 55% 100%)"></i><b>${p.name}</b>`;
  b.addEventListener('click',()=>applyPreset(i)); presetsEl.appendChild(b);
});
function applyPreset(i){
  presetIdx=i; const p=PRESETS[i];
  waxUniforms.uWaxColor.value.copy(p.wax); waxUniforms.uBulbColor.value.copy(p.bulb);
  liquidMat.color.copy(p.liquid); bulbLight.color.copy(p.bulb); spill.color.copy(p.bulb);
  bulbMat.emissive.copy(p.bulb);
  document.querySelectorAll('.preset').forEach((el,j)=>el.classList.toggle('active', j===i));
}
$('power').addEventListener('change',e=>{
  state.power=e.target.checked; $('powerLabel').textContent=state.power?'On':'Off';
  if(state.power){ state.warmup=0; } // wax must warm before first blob rises
  switchBtn.material.emissiveIntensity = state.power?0.7:0.02;
});
$('heat').addEventListener('input',e=>{ state.heat=parseFloat(e.target.value); $('heatOut').textContent=state.heat.toFixed(2)+'\u00D7'; });
$('waxAmt').addEventListener('input',e=>{ state.waxAmt=parseFloat(e.target.value); $('waxOut').textContent=Math.round(state.waxAmt*100)+'%'; });
$('room').addEventListener('input',e=>{ state.room=parseFloat(e.target.value); $('roomOut').textContent=Math.round(state.room*100)+'%'; });
$('slow').addEventListener('change',e=>{ state.slow=e.target.checked; });
$('orbit').addEventListener('change',e=>{ controls.autoRotate=e.target.checked; });
applyPreset(0);

/* ---------- flicker from wax occluding the bulb ---------- */
function bulbOcclusion(){
  let occ=0;
  for(const b of blobs){ if(!b.active) continue;
    const dx=b.pos.x, dz=b.pos.z, dy=b.pos.y-1.15;
    const d=Math.sqrt(dx*dx+dz*dz+dy*dy*0.6);
    occ += Math.exp(-d*d*3.5) * b.r*1.4;
  }
  return THREE.MathUtils.clamp(occ,0,0.55);
}

/* ---------- adaptive quality ---------- */
let fpsAcc=0, fpsN=0, fpsTimer=0;
function adaptQuality(dt){
  fpsAcc+=dt; fpsN++; fpsTimer+=dt;
  if(fpsTimer>2.5){
    const avg=fpsN/Math.max(fpsAcc,1e-3);
    if(avg<42 && waxUniforms.uSteps.value>34){ waxUniforms.uSteps.value-=8; renderer.setPixelRatio(Math.max(1.0, renderer.getPixelRatio()-0.15)); composer.setPixelRatio(renderer.getPixelRatio()); }
    else if(avg>57 && waxUniforms.uSteps.value<52){ waxUniforms.uSteps.value+=4; }
    fpsAcc=0; fpsN=0; fpsTimer=0;
  }
}

