const clock=new THREE.Clock();
let accumulator=0; const FIXED=1/60;
function animate(){
  requestAnimationFrame(animate);
  const rawDt=Math.min(clock.getDelta(), 0.05);
  const timeScale=state.slow?0.22:1.0;
  const dt=rawDt*timeScale;
  accumulator+=dt;
  let guard=0;
  while(accumulator>=FIXED && guard<4){ stepWax(FIXED); accumulator-=FIXED; guard++; }
  if(guard>=4) accumulator=0;
  syncWaxUniforms();
  // bulb + room respond to power, heat and wax occlusion (flicker/shift)
  const occ=bulbOcclusion();
  const flick=1 - occ*0.55 + Math.sin(state.time*13.7)*0.012*state.heatLevel + Math.sin(state.time*7.3+1.7)*0.01*state.heatLevel;
  const bulbI=(2.0+16*state.heatLevel)*flick;
  bulbLight.intensity=bulbI; spill.intensity=(0.5+5.0*state.heatLevel)*flick;
  bulbMat.emissiveIntensity=0.08+3.1*state.heatLevel*flick;
  bloom.strength=0.25+0.62*state.heatLevel;
  const rm=state.room;
  roomLight.intensity=rm*1.1; rimLight.intensity=0.06+rm*0.5; ambient.intensity=0.12+rm*0.85;
  scene.environmentIntensity=0.10+rm*0.55;
  gradePass.uniforms.uTime.value=performance.now()*0.001;
  controls.update();
  adaptQuality(rawDt);
  composer.render();
}
animate();

addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight; camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight); composer.setSize(innerWidth,innerHeight);
  gradePass.uniforms.uAspect.value=innerWidth/innerHeight;
});
